 .heroAside p { margin: 0 0 10px; color: var(--thorp-copy); font-size: var(--thorp-text-body, .84rem); line-height: 1.65; word-break: keep-all; }
 .heroAside p span { display: block; }
 .heroAside > span { color: var(--thorp-copy); font-size: var(--thorp-text-caption, .72rem); }
+/*
+  분야 구역 머리. 위 과거 사례·뉴스와 아래 분야 메뉴 사이에 서서 두 구역을 나눈다. 짜임(작은 제목·제목·오른쪽 안내)은
+  화면 머리와 같고 제목은 한 단계 작다. 작은 제목은 두 칸을 가로지르고, 새 디자인에서는 그 뒤로 오른쪽 끝으로 갈수록
+  옅어지는 선을 긋는다.
+*/
+.fieldSection { margin-top: 64px; }
+.sectionHead { display: grid; grid-template-columns: 1.2fr 1fr; gap: 0 40px; align-items: end; padding-bottom: 20px; }
+.sectionEyebrow { grid-column: 1 / -1; }
+.sectionHead h2 { margin: 6px 0 0; font: var(--thorp-title-weight, 600) clamp(1.35rem, 2vw, 1.65rem)/var(--thorp-title-leading, 1.18) var(--thorp-font-page, var(--thorp-font-body)); letter-spacing: var(--thorp-title-tracking, -.05em); word-break: keep-all; }
+.sectionHead h2 span { display: inline-block; color: var(--thorp-copy); white-space: nowrap; }
+:global(:root:not([data-design='classic'])) .sectionHead h2 span { color: inherit; }
+:global(:root:not([data-design='classic'])) .sectionHead .sectionEyebrow { display: flex; margin-bottom: 14px; }
+:global(:root:not([data-design='classic'])) .sectionHead .sectionEyebrow::after { flex: 1; height: 1px; background: linear-gradient(90deg, var(--thorp-line-strong), var(--thorp-line) 70%, transparent); content: ''; }
+.sectionLead { justify-self: end; max-width: 560px; margin: 0; padding: 0 0 3px 22px; border-left: 1px solid var(--thorp-line-strong); color: var(--thorp-copy); font-size: var(--thorp-text-body, .84rem); line-height: 1.65; word-break: keep-all; }
+.sectionLead span { display: block; }
+/* 중간 폭에서 안내 문장이 접힐 때 끝 낱말 하나만 아랫줄로 떨어지지 않게 한다. */
+.heroAside p span, .sectionLead span { text-wrap: pretty; }
 /* 분야 메뉴를 위에, 고른 분야의 상세를 그 아래 전체 폭으로 둔다. 옆으로 나누면 상세의 지표 칸이 좁아진다. */
 .workspace { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; align-items: start; border-bottom: 1px solid var(--thorp-line-strong); }
 .fieldRail { min-width: 0; }
